function fuelCost(distanceKm, consumptionL100, pricePerL, roundTrip){
  distanceKm=+distanceKm; consumptionL100=+consumptionL100; pricePerL=+pricePerL;
  if(!(distanceKm>0)||!(consumptionL100>0)||!(pricePerL>0)) return {error:'距离/油耗/油价须为正'};
  var dist = roundTrip ? distanceKm*2 : distanceKm;
  var liters = Math.round(dist/100*consumptionL100*1000)/1000;
  var cost = Math.round(liters*pricePerL*100)/100;
  return {distance:dist, liters:liters, cost:cost, roundTrip:!!roundTrip}; }
var EXPORTS={fuelCost:fuelCost};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FuelCostForgePure = EXPORTS; }
